import React, { useState, useEffect } from 'react';
import './App.css';
import ImageProcessor from './components/ImageProcessor';

function App() {
  const [colorblindType, setColorblindType] = useState('protanopia');
  const [mode, setMode] = useState('simulate');
  const [serverStatus, setServerStatus] = useState(null);

  useEffect(() => {
    const checkServer = async () => {
      try {
        const res = await fetch("http://127.0.0.1:5000/api/health");
        if (!res.ok) throw new Error("Server unreachable");
        const data = await res.json();
        if (data.status === "ok") setServerStatus(true);
        else setServerStatus(false);
      } catch (e) {
        setServerStatus(false);
      }
    };
    checkServer();
    const interval = setInterval(checkServer, 5000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="App">
      <header className="App-header">
        <h1>Color Blindness Friendly Filter</h1>
        <p>Process images for color blindness accessibility</p>
        <div
          style={{
            marginTop: '10px',
            padding: '8px 16px',
            borderRadius: '5px',
            backgroundColor: serverStatus ? 'rgba(76, 175, 80, 0.2)' : 'rgba(244, 67, 54, 0.2)',
            color: serverStatus ? '#4caf50' : '#f44336',
            fontSize: '14px',
            fontWeight: 'bold',
          }}
        >
          {serverStatus === null
            ? '⏳ Checking backend connection...'
            : serverStatus
            ? '✓ Backend server connected'
            : '✗ Backend server disconnected - Please start Flask server on port 5000'}
        </div>
      </header>

      <div className="controls">
        <div className="control-group">
          <label>Color Blindness Type:</label>
          <select value={colorblindType} onChange={(e) => setColorblindType(e.target.value)}>
            <option value="protanopia">Protanopia (Red-blind)</option>
            <option value="deuteranopia">Deuteranopia (Green-blind)</option>
            <option value="tritanopia">Tritanopia (Blue-blind)</option>
          </select>
        </div>
        <div className="control-group">
          <label>Mode:</label>
          <select value={mode} onChange={(e) => setMode(e.target.value)}>
            <option value="simulate">Simulate Color Blindness</option>
            <option value="enhance">Enhance for Color Blind</option>
          </select>
        </div>
      </div>

      <div className="content">
        <ImageProcessor colorblindType={colorblindType} mode={mode} />
      </div>
    </div>
  );
}

export default App;
